CREATE TYPE "Weekday" AS ENUM ('SATURDAY', 'SUNDAY', 'MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY');
CREATE TABLE "Room" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "capacity" INTEGER, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Room_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Room_code_key" ON "Room"("code");
CREATE TABLE "ClassRoutine" ("id" TEXT NOT NULL, "subjectAssignmentId" TEXT NOT NULL, "teacherId" TEXT NOT NULL, "roomId" TEXT NOT NULL, "academicSessionId" TEXT NOT NULL, "day" "Weekday" NOT NULL, "startTime" TEXT NOT NULL, "endTime" TEXT NOT NULL, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ClassRoutine_pkey" PRIMARY KEY ("id"), CONSTRAINT "ClassRoutine_subjectAssignmentId_fkey" FOREIGN KEY ("subjectAssignmentId") REFERENCES "SubjectAssignment"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "ClassRoutine_teacherId_fkey" FOREIGN KEY ("teacherId") REFERENCES "Teacher"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "ClassRoutine_roomId_fkey" FOREIGN KEY ("roomId") REFERENCES "Room"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "ClassRoutine_academicSessionId_fkey" FOREIGN KEY ("academicSessionId") REFERENCES "AcademicSession"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "ClassRoutine_academicSessionId_day_startTime_endTime_idx" ON "ClassRoutine"("academicSessionId", "day", "startTime", "endTime");
CREATE INDEX "ClassRoutine_teacherId_academicSessionId_day_idx" ON "ClassRoutine"("teacherId", "academicSessionId", "day");
CREATE INDEX "ClassRoutine_roomId_academicSessionId_day_idx" ON "ClassRoutine"("roomId", "academicSessionId", "day");
